// /frontend-react/src/components/HospitalizedHistoryPage.js

import React from 'react';
import { useTranslation } from 'react-i18next';
import HeaderBar from './HeaderBar';

// --- MOCK DATA ---
const detail = {
    title: "Hospital Stays",
    // Using simpleInfo for the main display, as it's typically a narrative for hospital stays
    simpleInfo: "You had a minor knee surgery (left leg) on May 10, 2022. The procedure was successful. No further action needed.",
    pdfLink: "Link_to_detailed_Surgical_Records_PDF.pdf",
    color: { bg: '#FFFDE7', border: '#FFD700', emoji: '🏥' },
};

const PHONE_MAX_WIDTH = '450px';

function HospitalizedHistoryPage({ isEasyMode, goToPage, onMenuClick }) {
    const { t } = useTranslation();
    
    // --- Styles ---
    // Removed detailCardStyle to clean up layout
    
    // Style for the main hospital event text (large and readable)
    const summaryTextStyle = {
        fontSize: isEasyMode ? '36px' : '22px',
        lineHeight: '1.4',
        fontWeight: 'bold', // Kept bold for prominence in Easy Mode
        color: '#333',
        margin: '20px auto 40px auto', // Centered and spaced text
        maxWidth: '380px',
        textAlign: 'center',
    };

    const preciseButtonStyle = {
        padding: '15px 30px',
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        borderRadius: '10px',
        border: 'none',
        cursor: 'pointer',
        marginTop: '10px',
        backgroundColor: '#DC3545', 
        color: 'white',
        boxShadow: '0 4px 10px rgba(0,0,0,0.3)',
        transition: 'background-color 0.2s',
    };

    const handleViewPrecise = () => {
        alert(`Opening PRECISE REPORT for ${detail.title} \nLink: ${detail.pdfLink}`);
        console.log(`Precise Report Link: ${detail.pdfLink}`);
    };

    return (
        <div 
            style={{ padding: '0 20px 20px 20px', maxWidth: PHONE_MAX_WIDTH, margin: '0 auto' }}
        >
            <HeaderBar
                title={detail.title}
                onBackClick={() => goToPage('medical-history')} 
                onMenuClick={onMenuClick}
                isEasyMode={isEasyMode}
            />

            {/* Simple Summary Header (Clean Spacing) */}
            <h2 style={{ 
                fontSize: isEasyMode ? '40px' : '30px', 
                margin: '30px 0 20px 0', // Spacing below HeaderBar
                color: detail.color.border, 
                textAlign: 'center' 
            }}>
                {t('history_details.simple_summary')}
            </h2>

            {/* Hospital Icon */}
            <div style={{textAlign: 'center', marginBottom: '20px'}}>
                <span style={{ fontSize: isEasyMode ? '90px' : '60px', display: 'block' }}>
                    {detail.color.emoji}
                </span>
            </div>

            {/* --- Easy Mode Summary Text --- */}
            <p style={summaryTextStyle}>
                {detail.simpleInfo}
            </p>
            
            {/* --- Call to Action for Caregivers/Others --- */}
            <h3 style={{ 
                fontSize: isEasyMode ? '30px' : '20px', 
                margin: '40px 0 10px 0', 
                textAlign: 'center', 
                color: '#666' 
            }}>
                {t('history_details.precise_access_prompt')}
            </h3>

            <div style={{ textAlign: 'center' }}>
                <button onClick={handleViewPrecise} style={preciseButtonStyle}>
                    {t('history_details.view_precise_report')}
                </button>
                <p style={{ fontSize: isEasyMode ? '18px' : '12px', marginTop: '15px', color: '#999' }}>
                    {t('history_details.precise_report_note')}
                </p>
            </div>
        </div>
    );
}

export default HospitalizedHistoryPage;
